<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">←</text><text class="nav-title">CSS渐变</text><text class="nav-icon" @click="randomGradient">🎲</text></view></view><view class="content"><view class="gradient-preview" :style="{ background: gradientCss }"></view><view class="gradient-code">{{ gradientCss }}</view><view class="color-row"><view class="color-item" v-for="(c, idx) in colors" :key="idx"><input type="color" :value="c" @input="colors[idx] = $event.detail.value; updateGradient()" class="color-input" /></view></view><view class="ctrl-row"><text class="ctrl-label">角度: {{ angle }}°</text><slider class="ctrl-slider" :value="angle" min="0" max="360" @change="angle = $event.detail.value; updateGradient()" block-size="16" /></view><view class="copy-btn" @click="copyCode"><text>复制CSS</text></view></view></view></template><script setup>import { ref, computed, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const colors = ref(["#667eea", "#764ba2"])
const angle = ref(135)
const gradientCss = computed(function() { return "linear-gradient(" + angle.value + "deg, " + colors.value.join(", ") + ")" })
function updateGradient() {}
function randomGradient() { colors.value = [["#ff6b6b","#feca57"],["#48dbfb","#0abde3"],["#a29bfe","#6c5ce7"],["#2ecc71","#27ae60"]][Math.floor(Math.random()*4)]; angle.value = Math.floor(Math.random()*360) }
function copyCode() { uni.setClipboardData({ data: gradientCss.value, success: function() { uni.showToast({ title: "已复制", icon: "success" }) } }) }
function goBack() { uni.navigateBack() }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#667eea,#764ba2);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:44rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.gradient-preview{height:300rpx;border-radius:20rpx;margin-bottom:24rpx}.gradient-code{background:#fff;border-radius:16rpx;padding:20rpx;font-size:24rpx;color:#333;font-family:monospace;margin-bottom:24rpx;word-break:break-all}.color-row{display:flex;gap:16rpx;margin-bottom:24rpx}.color-item{flex:1}.color-input{width:100%;height:80rpx;border:none;border-radius:12rpx}.ctrl-row{display:flex;align-items:center;margin-bottom:24rpx}.ctrl-label{font-size:26rpx;color:#666;width:120rpx}.ctrl-slider{flex:1}.copy-btn{background:linear-gradient(135deg,#667eea,#764ba2);border-radius:16rpx;padding:24rpx;text-align:center}.copy-btn text{font-size:30rpx;color:#fff;font-weight:600}</style>